// Transaction ngắn tách sang bean riêng, để mọi lời gọi đi qua proxy
@Service
class TopUpTxService {
    @Transactional
    public TopUp reserve(long walletId, String phone, long amount) {      // trừ ví + ghi PENDING
        walletRepository.debit(walletId, amount);
        return topUpRepository.save(TopUp.pending(walletId, phone, amount));
    }

    @Transactional
    public void markSuccess(long topUpId, String carrierRef) {
        topUpRepository.transition(topUpId, PENDING, SUCCESS, carrierRef);  // UPDATE ... WHERE status = 'PENDING'
    }

    @Transactional
    public void refund(long topUpId) {
        if (topUpRepository.transition(topUpId, PENDING, FAILED, null) == 1) {
            walletRepository.creditBack(topUpId);                          // chỉ hoàn khi chuyển trạng thái thành công
        }
    }
}

@Service
class TopUpService {
    public void topUp(long walletId, String phone, long amount) {        // không có @Transactional
        TopUp topUp = tx.reserve(walletId, phone, amount);
        try {
            TopUpResult result = carrierClient.topUp(phone, amount, topUp.id());  // id làm idempotency key
            tx.markSuccess(topUp.id(), result.ref());
        } catch (TopUpRejectedException e) {                                // nhà mạng từ chối rõ ràng
            tx.refund(topUp.id());
        } catch (TopUpException e) {                                        // timeout, 5xx: không biết đã nạp chưa
            // để PENDING, job đối soát hỏi lại nhà mạng bằng topUp.id()
        }
    }
}
